import { registerWebComponents } from '@domg-wc/common';
import { VlCascaderComponent } from '@domg-wc/components/block';

// VlCascaderComponent registreert zelf vl-cascader-item, vl-link, vl-icon en vl-text. De breadcrumb bovenaan tekent
// de cascader zelf, zonder vl-breadcrumb.
registerWebComponents([VlCascaderComponent]);

// Volgt bij een klik in de breadcrumb bovenaan. Het niveau staat in detail.levelClicked (0 voor het home-item, dan
// zonder label), het label van het item in detail.label.
document.querySelector('vl-cascader').addEventListener('vl-click-breadcrumb', (event) => {
    console.log(event.detail.levelClicked, event.detail.label);
});

import { registerWebComponents } from '@domg-wc/common';
import { VlAutocomplete, VlCascaderComponent, VlSideSheet } from '@domg-wc/components/block';

// Het slot breadcrumb-placeholder (hier een zoekveld) staat er zolang de breadcrumb er niet staat, dus op het
// eerste niveau.
registerWebComponents([VlSideSheet, VlCascaderComponent, VlAutocomplete]);

import { html, nothing } from 'lit';
import { registerWebComponents } from '@domg-wc/common';
import { VlTitleComponent } from '@domg-wc/components/atom';
import { VlCascaderComponent, VlInfoTile } from '@domg-wc/components/block';

// De cascader registreert zelf vl-cascader-item, vl-link en vl-text; vl-title en vl-info-tile niet.
registerWebComponents([VlCascaderComponent, VlInfoTile, VlTitleComponent]);

// Een template (TemplateFn) krijgt het item en processNarrowDown, en geeft een lit TemplateResult terug. Roep
// processNarrowDown(item) aan om het volgende niveau te tonen; zonder die aanroep kan de gebruiker niet verder.
const cascaderItemTemplates = new Map([
    [
        'provincie',
        (item, processNarrowDown) => {
            const hasChildren = item.children || item.narrowDown;
            const childrenAnnotation = html`Bekijk deelgemeentes
            ${item.children?.length
                ? html` <vl-text annotation>( ${item.children.length} )</vl-text> `
                : 'Bekijk deelgemeentes '}`;
            return html`
                <div class="vl-cascader-item">
                    <vl-title type="h3">${item.label}</vl-title>
                    <vl-link
                        bold
                        button-as-link
                        icon="${hasChildren ? 'arrow-right-fat' : nothing}"
                        icon-placement="after"
                        class="vl-cascader-link"
                        @click=${() => processNarrowDown(item)}
                    >
                        <span>
                            ${item.children ? childrenAnnotation : item.narrowDown ? 'Haal deelgemeentes op' : 'Actie'}
                        </span>
                    </vl-link>
                </div>
            `;
        },
    ],
]);

// Een vl-cascader-item met template-type zoekt zijn template op wanneer het rendert, en rendert niet opnieuw als
// templates later wijzigt: zet templates dus meteen, in hetzelfde script dat de componenten registreert.
document.querySelector('vl-cascader').templates = cascaderItemTemplates;

