// De cascader roept itemListFn(item) aan wanneer de gebruiker een item met narrowDown: true en zonder children
// opent, en toont wat de functie teruggeeft als volgende niveau. data.requestParams is data die je zelf meegeeft.
const getItemList = async (item) => {
    const { data } = item;
    const requestParams = data?.requestParams;
    // hier kan een API request gedefinieerd worden
    await new Promise((res) => setTimeout(res, 3000));
    return [
        {
            label: requestParams + ' ' + new Date().getHours(),
            children: [
                {
                    label: requestParams + ' ' + new Date().getMinutes(),
                    children: [
                        {
                            label: requestParams + ' ' + new Date().getMilliseconds(),
                            narrowDown: true,
                            data: {
                                requestParams: 'Niveau-deeper',
                            },
                        },
                        {
                            label: '[- ' + requestParams + ' -]',
                            templateType: 'provincie',
                        },
                    ],
                },
                {
                    label: requestParams + ' ' + new Date().getMinutes(),
                },
            ],
        },
        {
            label: requestParams + ' ' + new Date().getMinutes(),
            children: [
                {
                    label: requestParams + ' ' + new Date().getMilliseconds(),
                    narrowDown: true,
                    data: {
                        requestParams: 'Niveau-deeper',
                    },
                },
                {
                    label: '[- ' + requestParams + ' -]',
                    templateType: 'provincie',
                },
            ],
        },
        {
            label: requestParams + ' ' + new Date().getMinutes(),
        },
    ];
};

// Items met templateType 'provincie' krijgen deze template; de andere de standaardweergave.
const cascaderItemTemplates = new Map([
    [
        'provincie',
        (item, processNarrowDown) => {
            const hasChildren = item.children || item.narrowDown;
            const childrenAnnotation = html`Bekijk deelgemeentes
            ${item.children?.length
                ? html` <vl-text annotation>( ${item.children.length} )</vl-text> `
                : 'Bekijk deelgemeentes '}`;
            return html`
                <div class="vl-cascader-item">
                    <vl-title type="h3">${item.label}</vl-title>
                    <vl-link
                        bold
                        button-as-link
                        icon="${hasChildren ? 'arrow-right-fat' : nothing}"
                        icon-placement="after"
                        class="vl-cascader-link"
                        @click=${() => processNarrowDown(item)}
                    >
                        <span>
                            ${item.children ? childrenAnnotation : item.narrowDown ? 'Haal deelgemeentes op' : 'Actie'}
                        </span>
                    </vl-link>
                </div>
            `;
        },
    ],
]);

const cascader = document.querySelector('vl-cascader');
cascader.items = nodeData;
cascader.itemListFn = getItemList;
cascader.templates = cascaderItemTemplates;
